package forth

import (
	"errors"
	"strconv"
	"strings"
)

// wordFunc is a Forth word: it consumes a stack and returns the new stack.
type wordFunc func([]int) ([]int, error)

// Forth evaluates a sequence of lines of Forth source code and returns the
// final contents of the stack.
func Forth(input []string) ([]int, error) {
	stack := []int{}

	dict := map[string]wordFunc{
		"+": func(s []int) ([]int, error) {
			if len(s) < 2 {
				return nil, errors.New("only one value on the stack")
			}
			return append(s[:len(s)-2], s[len(s)-2]+s[len(s)-1]), nil
		},
		"-": func(s []int) ([]int, error) {
			if len(s) < 2 {
				return nil, errors.New("only one value on the stack")
			}
			return append(s[:len(s)-2], s[len(s)-2]-s[len(s)-1]), nil
		},
		"*": func(s []int) ([]int, error) {
			if len(s) < 2 {
				return nil, errors.New("only one value on the stack")
			}
			return append(s[:len(s)-2], s[len(s)-2]*s[len(s)-1]), nil
		},
		"/": func(s []int) ([]int, error) {
			if len(s) < 2 {
				return nil, errors.New("only one value on the stack")
			}
			if s[len(s)-1] == 0 {
				return nil, errors.New("divide by zero")
			}
			return append(s[:len(s)-2], s[len(s)-2]/s[len(s)-1]), nil
		},
		"dup": func(s []int) ([]int, error) {
			if len(s) < 1 {
				return nil, errors.New("empty stack")
			}
			return append(s, s[len(s)-1]), nil
		},
		"drop": func(s []int) ([]int, error) {
			if len(s) < 1 {
				return nil, errors.New("empty stack")
			}
			return s[:len(s)-1], nil
		},
		"swap": func(s []int) ([]int, error) {
			if len(s) < 2 {
				return nil, errors.New("only one value on the stack")
			}
			s[len(s)-2], s[len(s)-1] = s[len(s)-1], s[len(s)-2]
			return s, nil
		},
		"over": func(s []int) ([]int, error) {
			if len(s) < 2 {
				return nil, errors.New("only one value on the stack")
			}
			return append(s, s[len(s)-2]), nil
		},
	}

	defining := false
	expectName := false
	defName := ""
	def := []wordFunc{}

	for _, line := range input {
		for _, tok := range strings.Fields(line) {
			word := strings.ToLower(tok)

			if defining && expectName {
				if isNumber(word) {
					return nil, errors.New("illegal operation")
				}
				defName = word
				expectName = false
				continue
			}
			if defining {
				if word == ";" {
					body := def
					dict[defName] = func(s []int) ([]int, error) {
						for _, f := range body {
							var err error
							s, err = f(s)
							if err != nil {
								return nil, err
							}
						}
						return s, nil
					}
					defining = false
					continue
				}
				f, ok := dict[word]
				if !ok {
					return nil, errors.New("undefined operation")
				}
				def = append(def, f)
				continue
			}

			if word == ":" {
				defining = true
				expectName = true
				def = nil
				continue
			}
			if isNumber(word) {
				n, _ := strconv.Atoi(word)
				stack = append(stack, n)
				continue
			}
			f, ok := dict[word]
			if !ok {
				return nil, errors.New("undefined operation")
			}
			var err error
			stack, err = f(stack)
			if err != nil {
				return nil, err
			}
		}
	}

	return stack, nil
}

// isNumber reports whether tok is a (possibly negative) integer literal.
func isNumber(tok string) bool {
	_, err := strconv.Atoi(tok)
	return err == nil
}

